#include <bits/stdc++.h>
using namespace std;

const int INF=1e9+7;
struct Edge {
    int to, cap, cost, type;
    Edge(int t=0,int c=0,int v=0,int ty=0): to(t), cap(c), cost(v), type(ty) {}
};
vector<int> adj[100000];
Edge edges[1000000];
int edgeIdx;
int sinkNode;
int C, d;

void resetFlow(int sink) {
    sinkNode=sink;
    for (int i=0; i<=sink; ++i) adj[i].clear();
    edgeIdx=0;
}

void addEdge(int u, int v, int cap, int cost, int type) {
    adj[u].push_back(edgeIdx);
    edges[edgeIdx]=Edge(v,cap,cost,type);
    edgeIdx++;
    adj[v].push_back(edgeIdx);
    if (type==1) {
        edges[edgeIdx]=Edge(u,0,-C+d,type);
        edgeIdx++;
    } else {
        edges[edgeIdx]=Edge(u,0,-cost,type);
        edgeIdx++;
    }
}

int dist[100000], inQ[100000], queue[100000];
int minCost[100000];

int runFlow() {
    for (int i=0; i<=sinkNode; ++i) {
        minCost[i]=INF;
        inQ[i]=0;
    }
    minCost[sinkNode]=0;
    int front=0, back=1;
    queue[0]=0;
    while (front<back) {
        int u=queue[front++];
        inQ[u]=0;
        for (int r:adj[u]) {
            int v=edges[r].to;
            if (edges[r].cap>0 && minCost[u]+edges[r].cost<minCost[v]) {
                minCost[v]=minCost[u]+edges[r].cost;
                if (!inQ[v]) {
                    inQ[v]=1;
                    queue[back++]=v;
                }
            }
        }
    }
    if (minCost[sinkNode]==INF) return -1;
    int cur=sinkNode;
    while (cur!=0) {
        int r=0;
        for (int idx:adj[cur]) {
            if (edges[idx].to==cur && edges[idx^1].cap>0 && minCost[cur]==minCost[edges[idx].to]+edges[idx].cost) {
                r=idx;
                break;
            }
        }
        if (edges[r].type==1) {
            if ((r&1)==1) {
                edges[r].cost+=2*d;
                edges[r^1].cost-=2*d;
            } else {
                edges[r].cost+=2*d;
                edges[r^1].cost-=2*d;
            }
        }
        edges[r].cap--;
        edges[r^1].cap++;
        cur=edges[r^1].to;
    }
    return minCost[sinkNode];
}

int totalFlow(int n) {
    int total=0;
    for (int i=0; i<n; ++i) total+=runFlow();
    return total;
}

int main() {
    int n,m,k;
    cin>>n>>m>>k>>C>>d;
    resetFlow(n*100+1);
    for (int i=1; i<=k; ++i) {
        int x; cin>>x;
        addEdge(0,x,1,0,0);
    }
    for (int i=1; i<=99; ++i) {
        addEdge(1+i*n,100*n+1,INF,0,0);
    }
    for (int i=1; i<=n; ++i) {
        for (int j=1; j<=99; ++j) {
            addEdge(i+(j-1)*n,i+j*n,INF,C,0);
        }
    }
    for (int i=1; i<=m; ++i) {
        int x,y; cin>>x>>y;
        for (int j=1; j<=99; ++j) {
            addEdge(x+(j-1)*n,y+j*n,INF,C+d,1);
            addEdge(y+(j-1)*n,x+j*n,INF,C+d,1);
        }
    }
    cout<<totalFlow(k)<<endl;
    return 0;
}
